<div class="row g-4"><div class="col-xl-6"><div class="form-card"><div class="section-title"><i class="bi bi-person-circle"></i><div><h3>Profil Pengguna</h3><p><?= e($user['role_name']) ?></p></div></div><form method="post" action="<?= url('/profile') ?>"><?= csrf_field().method_field('PUT') ?><div class="mb-3"><label class="form-label">Nama</label><input class="form-control" name="name" value="<?= e($user['name']) ?>" required></div><div class="mb-3"><label class="form-label">Email</label><input type="email" class="form-control" name="email" value="<?= e($user['email']) ?>" required></div><div class="mb-3"><label class="form-label">Username</label><input class="form-control" value="<?= e($user['username']) ?>" disabled></div><button class="btn btn-primary">Simpan Profil</button></form></div></div><div class="col-xl-6"><div class="form-card"><div class="section-title"><i class="bi bi-key"></i><div x-data="{ showInfo: false }"><div class="d-inline-flex align-items-center gap-2"><h3 class="m-0">Ubah Password</h3><button type="button" @click="showInfo = !showInfo" class="info-toggle-btn" :class="{ 'is-active': showInfo }" :aria-expanded="showInfo.toString()" aria-label="Tampilkan info password" title="Informasi bantuan"><i class="bi bi-info-circle text-xs leading-none"></i></button></div><p x-show="showInfo" x-cloak x-transition style="display: none;">Gunakan minimal delapan karakter.</p></div></div><form method="post" action="<?= url('/profile/password') ?>"><?= csrf_field().method_field('PUT') ?><div class="mb-3"><label class="form-label">Password Saat Ini</label><input type="password" class="form-control" name="current_password" required></div><div class="mb-3"><label class="form-label">Password Baru</label><input type="password" class="form-control" name="new_password" required></div><div class="mb-3"><label class="form-label">Konfirmasi Password</label><input type="password" class="form-control" name="new_password_confirmation" required></div><button class="btn btn-primary">Ubah Password</button></form></div></div></div>
